import 'package:flutter/material.dart';
class AppColors { static const blue=Color(0xFF163E8C), teal=Color(0xFF0F9D9A), surface=Color(0xFFF6F8FC); }
class AppTheme { static ThemeData light() => build(Brightness.light); static ThemeData dark() => build(Brightness.dark); static ThemeData build(Brightness brightness) { final scheme=ColorScheme.fromSeed(seedColor:AppColors.blue,brightness:brightness,secondary:AppColors.teal); return ThemeData(useMaterial3:true,colorScheme:scheme,scaffoldBackgroundColor:brightness==Brightness.light?AppColors.surface:null,appBarTheme:AppBarTheme(centerTitle:false,backgroundColor:Colors.transparent,foregroundColor:scheme.onSurface,elevation:0),cardTheme:CardTheme(elevation:0,color:scheme.surface,borderRadius:BorderRadius.circular(22),margin:EdgeInsets.zero),inputDecorationTheme:InputDecorationTheme(filled:true,fillColor:scheme.surfaceContainerHighest,border:OutlineInputBorder(borderRadius:BorderRadius.circular(16),borderSide:BorderSide.none),contentPadding:const EdgeInsets.symmetric(horizontal:16,vertical:16))); } }
